"""Android operations"""
from builtins import str, range, object
import os
from time import sleep
import subprocess
import shlex
import json
import re
from taf.ul.trs_e2e_fw.lib.call_utils.exceptions import BandChangeFailedException, IpNotFoundException, \
    AdbExecutionError, AdbDeviceNotDetected, VoiceCallException, PingFailedException
from SSHLibrary import SSHClient
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.call_utils.mobile.key_events import KeyEvents

logger = BackgroundLogger.Instance()

MENU_MAPPER_FILE = 'menu_mapper.json'
MAX_VOICECALL_RETRIES = 10


class AndroidOperations(object):
    """
    Class for operations on android mobile using adb
    """

    def __init__(self, parent_rat, device_name, adb_id, band, ipv4_or_6):
        """
        Initializes class variables. Does SSH to UE PC, gets mobile version
        Args:
            parent_rat:
            device_name:
            adb_id:
            band:
        """
        self.parent_rat = parent_rat
        self.device_name = device_name
        self.ssh = self._start_ssh_to_ue_pc()
        self.mobile_adb_id = adb_id
        self.band = band
        self.ue_ip = None
        self.ipv4_or_6 = ipv4_or_6.strip().lower()

        self.key_events_obj = KeyEvents(self.mobile_adb_id)
        self.version = self._get_mobile_version()

    def switch_aeroplane_mode_on(self):
        """
        Switches Aeroplane mode to On and checks the mode status
        Returns: None

        """
        logger.info('Enabling Aeroplane Mode at UE')
        if self.version >= 900 or self.version < 410:
            if not self._get_aeroplane_mode_status():
                self._toggle_aeroplane_mode('enable')
                sleep(10)
            # this check is disables as some android devices were not responding to enable/disable cmd
            # as expected.
            # if not self._get_aeroplane_mode_status():
            #     raise Exception("Enabling Aeroplane Mode failed")
        # elif self.version > 4.1:
        else:
            self.execute_cmd("adb -s {0} shell settings put global airplane_mode_on 1")
            self.execute_cmd("adb -s {0} shell am broadcast -a android.intent"
                             ".action.AIRPLANE_MODE --ez state true")
            sleep(10)

    def switch_aeroplane_mode_off(self):
        """
        Switches Aeroplane mode to Off and checks the mode status
        Returns: None
        """
        logger.info('Disabling Aeroplane Mode enable at UE')
        logger.info('android version: {}'.format(self.version))
        # logger.info('version is >= 9: {}'.format(self.version >= 900))
        if self.version >= 900 or self.version < 410:
            if self._get_aeroplane_mode_status():
                self._toggle_aeroplane_mode('disable')
                sleep(10)
            # this check is disables as some android devices were not responding to enable/disable cmd
            # as expected.
            # if self._get_aeroplane_mode_status():
            #     raise Exception("Disabling Aeroplane Mode failed")
        else:
            self.execute_cmd("adb -s {0} shell settings put global airplane"
                             "_mode_on 0")
            self.execute_cmd("adb -s {0} shell am broadcast -a android.intent"
                             ".action.AIRPLANE_MODE --ez state false")
            sleep(20)
            self.execute_cmd("adb -s {0} shell getprop | grep gsm.network")

    def start_voice_call(self):
        """
        Starts voice call to number 123456 and checks the call status
        Returns: None

        """
        return_output = self.execute_cmd(
            "adb -s {0} shell am start -a android.intent.action.CALL -d tel:123456")
        logger.debug(return_output)
        sleep(10)
        self._check_voice_call_status_to_be_connected()

    def end_voice_call(self):
        """
        Ends voice call and checks the call status
        Returns: None

        """
        if self.version > 410:
            self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_ENDCALL")
        else:
            self.execute_cmd("adb -s {0} shell input keyevent 6")
        sleep(5)
        self._check_voice_call_status_to_be_disconnected()

    def change_band(self, max_band_change_retries=6):
        """Change band"""
        for retry_attempt in range(max_band_change_retries):
            sleep(5)
            logger.info('Changing Band to {0}  {1}::attempt :: {2}'.format(
                self.parent_rat, self.band, retry_attempt))
            self._select_band()
            menu_mapper_file = os.path.abspath(
                os.path.join(__file__, os.pardir, os.pardir, 'resources', MENU_MAPPER_FILE))
            with open(menu_mapper_file, 'r') as menu_obj:
                menu_dict = json.load(menu_obj)
                self.key_events_obj.select_item(
                    menu_dict['menu_mapper']['tech'][self.parent_rat])
                self.key_events_obj.select_item(
                    menu_dict['menu_mapper']['{}_bands'.format(
                        self.parent_rat)][self.band])
            sleep(5)
            match = self._verify_string_in_screen_shot('Band')
            if match:
                break
            else:
                self._clear_all_apps()
                logger.info("Band change Attempt: {}".format(retry_attempt))
                self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_HOME")
                if retry_attempt == max_band_change_retries - 1:
                    raise BandChangeFailedException(
                        "Changing Band To {0} Unsuccessful".format(
                            self.parent_rat))
        self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_HOME")

    def get_ue_ip(self):
        """Get ue ip"""
        # console_output = self.execute_cmd("adb  -s  {0} shell ip addr show"
        #                                   " rmnet0 >ipDetails.txt")
        user_mobile_ip_interface = get_config_variable(
            ['ue_devices', self.parent_rat, self.device_name,
             'mobile_ip_interface'])
        mobile_ip_interface = 'rmnet0' if not user_mobile_ip_interface else user_mobile_ip_interface
        console_output = self.execute_cmd("adb  -s  {0} shell ip addr show " + mobile_ip_interface)
        logger.debug("UE IP Console Output : {}".format(console_output))

        # ip_regex = self._get_ip_regex()
        # ## To be uncommented after ipv6 ip assignment for wcdma ipv6
        # calls is supported
        # ip_matches = re.findall("inet\\s*(\\d+\.\\d+\.\\d+\.\\d+)",
        #                         console_output)
        # ip_matches = re.findall(ip_regex, console_output)
        # #To be uncommented after ipv6 ip assignment for wcdma ipv6 calls is
        # supported

        # Adding below code only untill ipv6 ip assignment for wcdma ipv6
        # calls is not supported
        ipv4_regex = r'inet (addr)?\s*:?\s*(.*?)(/\d+)?\s+'
        ipv6_regex = r'inet6 (addr)?\s*:?\s*(.*?)(/\d+)?\s*scope global'
        ip_matches = []
        for regex in [ipv6_regex, ipv4_regex]:
            ip_matches = re.findall(regex, console_output)
            if ip_matches:
                break
        # Adding above code only untill ipv6 ip assignment for wcdma ipv6
        # calls is not supported

        logger.debug("UE IP Regex match: {0}".format(str(ip_matches)))
        if len(ip_matches) > 0:
            logger.info("UE IP: {0}".format(ip_matches[0][:]))
            return ip_matches[0][1]
        raise IpNotFoundException()

    def execute_cmd(self, cmd):
        """Execute command"""
        mobile_params = get_config_variable(['ue_devices', self.parent_rat,
                                             self.device_name])
        logger.debug(cmd.format(self.mobile_adb_id))
        if mobile_params.get('remote_ip'):
            return self.start_process_remote(cmd.format(self.mobile_adb_id))
        else:
            return subprocess.check_output(cmd.format(self.mobile_adb_id), shell=True)

    def start_process_remote(self, cmd):
        """ Start process.

        :param string cmd:      Command to run.
        """
        out, err, rc = self.ssh.execute_command(cmd)
        out = out.strip()
        err = err.strip()
        logger.debug("Remote process output:{0}", out)
        if rc == 0:
            return out
        else:
            raise AdbExecutionError(err)

    def get_network_parameter(self):
        """Get network parameter"""
        if self.parent_rat.upper() == "LTE":
            self._run_network_signal_info_app()
        else:
            self._dial_secret_number_on_dial_pad()
        self._take_screen_shot()
        screenshot_content = self._get_text_from_screen_shot()
        return self._get_cell_details_from_screenshot_text(screenshot_content)

    def select_apn(self):
        """Select apn"""
        if self._get_mobile_version() == 500 or self._get_mobile_version() == '5.0':
            self.execute_cmd("adb -s {0} shell am start - a android.settings.APN_SETTINGS")
            v4_or_v6_apn_key = 19 if self.ipv4_or_6 == 'ipv4' else 20
            for keynum in [v4_or_v6_apn_key, 22, 23, 3]:
                self.execute_cmd("adb -s {{}} shell input keyevent {}".format(keynum))
                sleep(2)
            self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_HOME")
        else:
            logger.info('Skipping APN changes. APN Change is supported for Android 5.0 only')

    def _get_ip_regex(self):
        ipv4_regex = r'inet (addr)?\s*:?\s*(.*?)(/\d+)?\s+'
        ipv6_regex = r'inet6 (addr)?\s*:?\s*(.*?)(/\d+)?\s*scope global'
        ip_regex = ipv4_regex if self.ipv4_or_6 == 'ipv4' else ipv6_regex
        logger.debug('IP Regex to be applied: {}'.format(ip_regex))
        return ip_regex

    def _start_ssh_to_ue_pc(self):
        mobile_params = get_config_variable(['ue_devices', self.parent_rat, self.device_name])
        if mobile_params.get('remote_ip'):
            ssh_client = SSHClient(get_config_variable(['ue_devices',
                                                        self.parent_rat,
                                                        self.device_name,
                                                        'remote_ip']),
                                   port=22, prompt='$', timeout=10)
            ssh_client.login(get_config_variable(
                ['ue_devices', self.parent_rat, self.device_name,
                 'remote_user']),
                get_config_variable(['ue_devices',
                                     self.parent_rat,
                                     self.device_name,
                                     'remote_password']))
        else:
            ssh_client = None
        return ssh_client

    def _clear_all_apps(self):
        key_list = ["187", "152", "152", "22", "23", "KEYCODE_HOME"]
        self.key_events_obj.key_event_sequence(key_list)

    def _reboot_via_app(self):
        self._clear_all_apps()
        reboot_sqnc = ["keyevent KEYCODE_SEARCH", "text reboot", "100 300", "500 700", "800 1080"]

        for item in reboot_sqnc:
            cmd = "adb -s {0} shell input {1}".format(self.mobile_adb_id, item)
            logger.info(cmd)
            self.execute_cmd(cmd)
            sleep(2)
        return

    def _reboot_device_using_id(self):
        # reboot the device using its serial number and wait for it to come up
        self.execute_cmd("adb -s {} reboot".format(self.mobile_adb_id))
        logger.debug("Waiting for 2 minutes for ADB to restart")
        sleep(120)
        self._check_mobile_is_up()

    def _check_mobile_is_up(self, retry_attempts=5, time_interval=30):
        for attempt in range(retry_attempts):
            output = self.execute_cmd("adb devices")
            if re.findall(self.mobile_adb_id, output, re.DOTALL):
                logger.info("ADB Device Detected")
                break
            else:
                sleep(time_interval)
        else:
            logger.warn("ADB Device Not Detected")
            raise AdbDeviceNotDetected()
        return

    def _check_voice_call_status_to_be_connected(self):
        self._check_mcallstate_repeatedly(value=2)

    def _check_voice_call_status_to_be_disconnected(self):
        self._check_mcallstate_repeatedly(value=0)

    def _get_mcallstate(self):
        if self.version > 410:
            callstate = self.execute_cmd(
                "adb -s {0} shell dumpsys telephony.registry | grep mCallState")
        else:
            callstate = self.execute_cmd(
                "adb -s {0} shell dumpsys telephony.msim.registry | grep mCallState")
        logger.info(callstate)
        number = re.findall(r'mCallState=(\d+)', callstate)
        return number

    def _check_mcallstate_value(self, mcallstate, value):
        if int(mcallstate[0]) != value:
            raise VoiceCallException('mCallState value is not {}. '.format(
                value))

    def _check_mcallstate_repeatedly(self, value):
        for time_attempt in range(MAX_VOICECALL_RETRIES):
            try:
                number = self._get_mcallstate()
                self._check_mcallstate_value(number, value)
                return True
            except VoiceCallException as e:
                logger.debug("INFO: {}".format(e))
                sleep(5)
                if time_attempt == MAX_VOICECALL_RETRIES - 1:
                    raise VoiceCallException('mCallState value is not {}. '.format(value))
                else:
                    continue

    def _adb_ping(self, ping_packets_count, ip_to_ping):
        cmd = shlex.split(
            "adb -s {0} shell su -c  ping -c {1} {2}".format(
                self.mobile_adb_id, ping_packets_count, ip_to_ping))
        output = self.execute_cmd(cmd)
        percentage_loss = re.findall(r'received,\s*(.*?)\%\s*packet\s*loss', output)
        if int(percentage_loss[0]) > 30 or not percentage_loss:
            raise PingFailedException()

    def _verify_string_in_screen_shot(self, search_string):
        self.execute_cmd("adb -s {0} shell settings put system screen_brightness 300")
        self.execute_cmd("adb -s {0} shell /system/bin/screencap -p /sdcard/screenshot.png")
        self.execute_cmd("adb -s {0} pull /sdcard/screenshot.png screenshot.png")
        sleep(3)
        self.execute_cmd("tesseract screenshot.png screen_txt")
        with open('screen_txt.txt', 'r') as screen:
            screen_content = screen.read()
        match = re.findall(search_string, screen_content, re.DOTALL)
        self.execute_cmd("sudo rm screenshot.png; sudo rm screen_txt.txt")
        return match

    def _select_band(self, max_band_change_retries=6):
        for retry in range(max_band_change_retries):
            for _ in range(3):
                self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_HOME")
            sleep(5)
            self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_CALL")
            for _ in range(3):
                self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_DEL")
            sleep(4)
            self.execute_cmd("adb -s {0} shell input text *#0011#")
            sleep(2)
            match = self._verify_string_in_screen_shot('NETWORK')
            if match:
                break
            else:
                self._clear_all_apps()

        self.key_events_obj.go_to_back_in_menu()
        self.key_events_obj.go_to_key_event_in_menu()
        self.key_events_obj.enter_key_event('Q')
        self.key_events_obj.go_to_key_event_in_menu()
        self.key_events_obj.enter_key_event('0000')
        sleep(15)
        # select ue settings & info->setting->PROTOCOL->NAS->NETWORK CONTROL->
        # BAND SELECTION
        set_list_sqnc = ['2', '1', '1', '2', '1', '4']
        for item in set_list_sqnc:
            self.key_events_obj.select_item(item)

    def _get_mobile_version(self):
        mobile_version = self.execute_cmd("adb -s {} shell getprop | grep ro.build.version.release")
        match = re.findall(r':\s*\[(.*?)\]', mobile_version, re.DOTALL)
        version_digits = match[0].split('.')
        num_of_zeroes = 3 - len(version_digits)
        version = ''.join(version_digits) + num_of_zeroes * '0'
        version = int(version)
        # version = float(match[0])
        logger.info('Android Version {}'.format(version))
        return version

    def _get_aeroplane_mode_status(self):
        status = None

        # check if the device is listed, otherwise raise an exception
        try:
            self._check_mobile_is_up()
        except AdbDeviceNotDetected as e:
            logger.warn("Exception: {} \n Adb device with id {} not detected".format(e, str(self.mobile_adb_id)))
            self._reboot_device_using_id()

        if self.version >= 900:
            service_state = self.execute_cmd(
                "adb -s {0} shell dumpsys telephony.registry | grep -i "
                "mServiceState | tail -1")
            service_state_number = re.findall(r'mDataRegState=(\d+)',
                                              service_state)
            logger.debug("Service state: {}".format(service_state))
            if int(service_state_number[0]) == 0:
                status = False
            else:
                status = True
        else:
            service_state = self.execute_cmd("adb -s {0} shell dumpsys telephony.msim.registry | grep mServiceState")
            service_state_number = re.findall(r'mServiceState=(\d+)', service_state)
            logger.debug("Service state: {}".format(service_state))
            if int(service_state_number[0]) == 3:
                status = True
            else:
                status = False
        logger.info('Aeroplane mode status: {}'.format(status))
        return status

    def _toggle_aeroplane_mode(self, state):
        if self.version >= 900:
            service_call_number = get_config_variable(['ue_devices', self.parent_rat,
                                                       self.device_name, 'service_call_number'])
            logger.debug(service_call_number)
            self.execute_cmd("adb -s {0} shell input keyevent 3")
            self.execute_cmd("adb -s {0} shell input keyevent 3")
#            self.execute_cmd("adb -s {0} shell am start -W -a android.settings.AIRPLANE_MODE_SETTINGS "
#                             "--activity-clear-task")
            sleep(20)
            self.execute_cmd("adb -s {0} shell cmd connectivity airplane-mode {1}".format(self.mobile_adb_id, state))
#            self.execute_cmd('adb -s {0} shell service call phone {1}'.format('{0}', service_call_number))
        else:
            logger.info('Toggling aeroplane mode')
            self.execute_cmd("adb -s {0} shell input keyevent 3")
            sleep(2)
            self.execute_cmd('adb -s {} shell monkey -p jp.android.airpalnemode -c android.intent.category.LAUNCHER 1')
        sleep(5)

    def _dial_secret_number_on_dial_pad(self):
        logger.info("opening dialer app and typing number...")
        self._switch_on_screen()
        self.execute_cmd("adb -s {0} shell monkey -p com.android.contacts 1")
        sleep(3)
        # coordinate_x, coordinate_y = self._get_x_y_coordinate_to_click_keypad_option()
        if str(self._get_mobile_version()) == "5.0":
            self.execute_cmd("adb -s {0} shell input tap {0} {1}".format("114", "224"))
        self.execute_cmd("adb -s {0} shell input text *#0011#")
        sleep(3)

    def _switch_on_screen(self):
        if not self._is_screen_on():
            if self.android_version == "5.0":
                self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_POWER")
            else:
                self.execute_cmd("adb -s {0} shell input keyevent 1")

    def _take_screen_shot(self):
        logger.debug("Taking screenshot....")
        self.execute_cmd("adb -s {0} shell settings put system screen_brightness 300")
        self.execute_cmd("adb -s {0} shell /system/bin/screencap -p /sdcard/screenshot_adb.png")
        self.execute_cmd("adb -s {0} pull /sdcard/screenshot_adb.png screenshot_adb.png")
        sleep(3)

    def _get_text_from_screen_shot(self):
        logger.debug("Executing tesseract...")
        self.execute_cmd("tesseract screenshot_adb.png screen_txt_adb")
        with open('screen_txt_adb.txt', 'r') as screen:
            screen_content = screen.read()
        logger.info("screen content text :: {}".format(screen_content))
        return screen_content

    def _get_cell_details_from_screenshot_text(self, screenshot_content):
        logger.debug("Getting NW details from tessaract output...")
        regx_pattern = self._get_regx_pattern()
        re_object = self._get_re_object(regx_pattern, screenshot_content)
        return self._cell_detatils_from_re_object(re_object)

    def _get_re_object(self, regx_pattern, screenshot_content):
        logger.debug("Obtaining re_object")
        re_object = re.search(regx_pattern, screenshot_content)
        if not re_object:
            BuiltIn().fail("Fail :: Could not find host details from screenshot")
        return re_object

    def _cell_detatils_from_re_object(self, re_object):
        logger.info("Obtaining cell info")
        if self.parent_rat.upper() == "WCDMA":
            return self._cell_detatils_from_wcdma_re_object(re_object)
        else:
            return self._cell_detatils_from_lte_re_object(re_object)

    def _cell_detatils_from_wcdma_re_object(self, re_object):
        cell_details = {}
        cell_details["MCC"] = re_object.group(1)
        cell_details["MNC"] = re_object.group(2)
        cell_details["CID"] = int(re_object.group(3)[-4:], 16)
        logger.info("Cell details :: {}".format(str(cell_details)))
        return cell_details

    def _cell_detatils_from_lte_re_object(self, re_object):
        cell_details = {}
        cell_details["ECI"] = re_object.group(1)
        cell_details["ENbI"] = re_object.group(2)
        cell_details["TAC"] = re_object.group(3)
        cell_details["MCC"] = re_object.group(4)
        cell_details["MNC"] = re_object.group(5)
        logger.info("Cell details :: {}".format(str(cell_details)))
        return cell_details

    def _get_regx_pattern(self):
        regx_pattern = {
            "5.0": {
                "LTE": r"Cell:\s+(\d+).*\n(\d+).*\n(\d+).+\n+MNC:\s+(\d+).+\n+MCC:\s+(\d+).+",
                "WCDMA": r"PLMN[\w:](\d+)-(\d+)\n+RX.+[-+]\d+.+C[\|Il]D:*(\w+)"
            },
            "4.0.4": {
                "WCDMA": r"MCC.MNC\s+:\s+(\d+)\s+.\s+(\d+)\n+RX:\s+\d+,\s+.+:\s+.\d+,\s+.+:\s+(\d+)"
            }
        }
        regx = regx_pattern[self.android_version][self.parent_rat.upper()]
        logger.debug("Regx Pattern :: {}".format(regx))
        return regx

    def _run_network_signal_info_app(self):
        if not self._is_screen_on():
            self.execute_cmd("adb -s {0} shell input keyevent KEYCODE_POWER")
        self.execute_cmd("adb -s {0} shell monkey -p de.android.telnet 1")
        logger.debug("opening Network signal info app")
        sleep(3)

    def _is_screen_on(self):
        self.android_version = str(self._get_mobile_version())
        if self.android_version == "5.0" and "ON".encode('utf-8') in self.execute_cmd(
                "adb -s {0} shell dumpsys power | grep \"Display Power\""):
            logger.debug("Phone screen is on")
            return True
        if self.android_version == "4.0.4" and self.execute_cmd(
                "adb -s {0} shell dumpsys power | grep \"mPowerState=3\""):
            logger.debug("Phone screen is on")
            return True
        else:
            logger.debug("Phone screen is off.Switching on")
            return False
